37	/* 3x3 same padding, stride 1, +ReLU. w 布局 (kh,kw,in,out), b[out] */
38	static void conv3x3_same_relu(const float *in, int H, int W, int Cin,
39	                              const float *w, const float *b, int Cout,
40	                              float *out) {
41	  for (int o = 0; o < Cout; ++o) {
42	    for (int h = 0; h < H; ++h) {
43	      for (int p = 0; p < W; ++p) {
44	        float acc = b[o];
45	        for (int kh = 0; kh < 3; ++kh) {
46	          int ih = h + kh - 1;
47	          if (ih < 0 || ih >= H) continue;
48	          for (int kw = 0; kw < 3; ++kw) {
49	            int iw = p + kw - 1;
50	            if (iw < 0 || iw >= W) continue;
51	            const float *ip = in + ((ih * W) + iw) * Cin;
52	            for (int c = 0; c < Cin; ++c)
53	              acc += ip[c] * w[(((kh * 3) + kw) * Cin + c) * Cout + o];
54	          }
55	        }
56	        out[((h * W) + p) * Cout + o] = acc > 0 ? acc : 0;
57	      }
58	    }
59	  }
